import { Duration, Effect, Schedule } from "effect";

import type { HevyHttpError } from "./hevy-http-error.js";
import {
	DEFAULT_RETRY_POLICY,
	getRetryDelayMs,
	type RetryPolicy,
} from "./retry-policy.js";

export type RetryScheduleInput = Pick<HevyHttpError, "status" | "headers">;

/**
 * Builds the Effect schedule used by retrying client programs.
 *
 * The schedule deliberately only owns retry timing and the retry count. The
 * client remains responsible for deciding whether an error is safe to retry,
 * preserving its HTTP execution metadata and observation lifecycle.
 */
export function createRetrySchedule(
	maxRetries: number,
	policy: RetryPolicy = DEFAULT_RETRY_POLICY,
	randomInt = (maxExclusive: number) =>
		Math.floor(Math.random() * maxExclusive),
): Schedule.Schedule<number, RetryScheduleInput> {
	return Schedule.recurs(Math.max(0, maxRetries)).pipe(
		Schedule.addDelay((metadata) =>
			Effect.sync(() => {
				return Duration.millis(
					getRetryDelayMs(metadata.input, metadata.attempt, policy, randomInt),
				);
			}),
		),
	);
}

import type { HevyHttpError } from "./hevy-http-error.js";

export const RETRY_BACKOFF_MAX_MS = 5_000;
export const RETRY_BACKOFF_BASE_MS = 300;

export interface RetryPolicy {
	readonly maxRetries: number;
	readonly baseDelayMs: number;
	readonly maxDelayMs: number;
}

export const DEFAULT_RETRY_POLICY: RetryPolicy = {
	maxRetries: 3,
	baseDelayMs: RETRY_BACKOFF_BASE_MS,
	maxDelayMs: RETRY_BACKOFF_MAX_MS,
};

export function parseRetryAfterMs(
	value: string | null,
	now = Date.now(),
): number | undefined {
	if (!value) return undefined;
	const seconds = Number(value);
	if (Number.isFinite(seconds) && seconds >= 0) {
		return Math.round(seconds * 1_000);
	}
	const dateMillis = Date.parse(value);
	return Number.isNaN(dateMillis) ? undefined : Math.max(0, dateMillis - now);
}

/**
 * Calculate the next retry delay without performing I/O.
 *
 * Keeping this policy pure makes it independently testable and provides the
 * seam for replacing the imperative retry loop with an Effect Schedule.
 */
export function getRetryDelayMs(
	error: Pick<HevyHttpError, "status" | "headers">,
	retryAttempt: number,
	policy: RetryPolicy = DEFAULT_RETRY_POLICY,
	randomInt = (maxExclusive: number) =>
		Math.floor(Math.random() * maxExclusive),
): number {
	const exponential = Math.min(
		policy.maxDelayMs,
		policy.baseDelayMs * 2 ** Math.max(0, retryAttempt - 1),
	);
	const retryAfter =
		error.status === 429
			? parseRetryAfterMs(error.headers?.get("retry-after") ?? null)
			: undefined;
	const lowerBound =
		retryAfter === undefined ? exponential : Math.max(exponential, retryAfter);
	const jitterLimit =
		retryAfter === undefined
			? 250
			: Math.min(250, Math.max(1, retryAfter * 0.1));
	const jitter = randomInt(Math.ceil(jitterLimit));
	return lowerBound + jitter;
}

import { Data, Duration, Effect } from "effect";

import type { HevyOperationSafety } from "./execution.js";

export interface BackoffFailureOptions {
	readonly cause: unknown;
	readonly method: string;
	readonly endpoint: string;
	readonly phase: "backoff";
	readonly operationSafety: HevyOperationSafety;
	readonly deadline?: number;
}

/** Internal typed failure used while adapting a retry wait. */
export class BackoffFailure extends Data.TaggedError("BackoffFailure")<{
	readonly cause: unknown;
	readonly method: string;
	readonly endpoint: string;
	readonly phase: "backoff";
	readonly operationSafety: HevyOperationSafety;
	readonly deadline?: number;
}> {}

function interruptionEffect(
	signal: AbortSignal,
): Effect.Effect<never, unknown> {
	return Effect.callback<never, unknown>((resume, interruptionSignal) => {
		const cleanup = () => {
			signal.removeEventListener("abort", fail);
			interruptionSignal.removeEventListener("abort", cleanup);
		};
		const fail = () =>
			resume(
				Effect.fail(
					signal.reason ?? new DOMException("Operation canceled", "AbortError"),
				),
			);
		if (signal.aborted) {
			fail();
			return;
		}
		signal.addEventListener("abort", fail, { once: true });
		interruptionSignal.addEventListener("abort", cleanup, { once: true });
		return Effect.sync(cleanup);
	}).pipe(Effect.interruptible);
}

/**
 * Wait using the Effect Clock while still observing the operation signal.
 * This is deliberately separate from the Promise adapter so TestClock can
 * control the actual production retry wait.
 */
export function effectClockSleep(
	delayMs: number,
	signal: AbortSignal,
): Effect.Effect<void, unknown> {
	if (signal.aborted) {
		return Effect.fail(
			signal.reason ?? new DOMException("Operation canceled", "AbortError"),
		);
	}
	const sleep = Effect.sleep(Duration.millis(Math.max(0, delayMs)));
	return Effect.raceFirst(sleep, interruptionEffect(signal)).pipe(
		Effect.asVoid,
	);
}

/**
 * Adapt the established Promise sleep hook to an interruptible Effect.
 * Synchronous throws are captured by tryPromise just like rejections.
 */
export function customPromiseSleep(
	delayMs: number,
	signal: AbortSignal,
	sleep: (milliseconds: number, signal?: AbortSignal) => Promise<void>,
): Effect.Effect<void, unknown> {
	return Effect.tryPromise({
		try: (interruptionSignal) => {
			if (signal.aborted) {
				return Promise.reject(
					signal.reason ?? new DOMException("Operation canceled", "AbortError"),
				);
			}
			return new Promise<void>((resolve, reject) => {
				let settled = false;
				const cleanup = () => {
					signal.removeEventListener("abort", onOperationAbort);
					interruptionSignal.removeEventListener("abort", onInterruptionAbort);
				};
				const settleReject = (cause: unknown) => {
					if (settled) return;
					settled = true;
					cleanup();
					reject(cause);
				};
				const onOperationAbort = () =>
					settleReject(
						signal.reason ??
							new DOMException("Operation canceled", "AbortError"),
					);
				const onInterruptionAbort = () =>
					settleReject(new DOMException("Effect interrupted", "AbortError"));
				signal.addEventListener("abort", onOperationAbort, { once: true });
				interruptionSignal.addEventListener("abort", onInterruptionAbort, {
					once: true,
				});
				if (signal.aborted) {
					onOperationAbort();
					return;
				}
				try {
					Promise.resolve(sleep(delayMs, signal)).then(() => {
						if (settled) return;
						settled = true;
						cleanup();
						resolve();
					}, settleReject);
				} catch (cause) {
					settleReject(cause);
				}
			});
		},
		catch: (cause) => cause,
	});
}

export function retryBackoff(
	options: BackoffFailureOptions & {
		readonly delayMs: number;
		readonly sleep?: (
			milliseconds: number,
			signal?: AbortSignal,
		) => Promise<void>;
		readonly signal: AbortSignal;
	},
): Effect.Effect<void, BackoffFailure> {
	const wait = options.sleep
		? customPromiseSleep(options.delayMs, options.signal, options.sleep)
		: effectClockSleep(options.delayMs, options.signal);
	return wait.pipe(
		Effect.mapError(
			(cause) =>
				new BackoffFailure({
					cause,
					method: options.method,
					endpoint: options.endpoint,
					phase: "backoff",
					operationSafety: options.operationSafety,
					deadline: options.deadline,
				}),
		),
	);
}

import { Data, Effect } from "effect";

import type {
	HevyCommitState,
	HevyOperationSafety,
	HevyRequestPhase,
} from "./execution.js";

export interface AttemptFailureOptions {
	readonly cause: unknown;
	readonly method: string;
	readonly endpoint: string;
	readonly phase: HevyRequestPhase;
	readonly operationSafety: HevyOperationSafety;
	readonly commitState: HevyCommitState;
	readonly responseConfirmed: boolean;
	readonly deadline?: number;
	readonly retryCount: number;
}

/** Typed internal channel for a dispatch or response-consumption failure. */
export class AttemptFailure extends Data.TaggedError("AttemptFailure")<{
	readonly cause: unknown;
	readonly method: string;
	readonly endpoint: string;
	readonly phase: HevyRequestPhase;
	readonly operationSafety: HevyOperationSafety;
	readonly commitState: HevyCommitState;
	readonly responseConfirmed: boolean;
	readonly deadline?: number;
	readonly retryCount: number;
}> {}

/**
 * Adapt one asynchronous attempt to Effect while retaining the metadata
 * needed by the transition policy if the adapter itself throws.
 */
export function attemptEffect<A>(
	options: AttemptFailureOptions & {
		readonly run: (signal: AbortSignal) => Promise<A>;
	},
): Effect.Effect<A, AttemptFailure> {
	return Effect.tryPromise({
		try: options.run,
		catch: (cause) =>
			new AttemptFailure({
				cause,
				method: options.method,
				endpoint: options.endpoint,
				phase: options.phase,
				operationSafety: options.operationSafety,
				commitState: options.commitState,
				responseConfirmed: options.responseConfirmed,
				deadline: options.deadline,
				retryCount: options.retryCount,
			}),
	});
}

/** Make observer and resource finalizers idempotent at their Effect seam. */
export function finalizeOnce(finalizer: () => void): () => void {
	let finalized = false;
	return () => {
		if (finalized) return;
		finalized = true;
		try {
			finalizer();
		} catch {
			// Resource finalization is best-effort and cannot replace settlement.
		}
	};
}

/**
 * Runtime-neutral execution control shared by every Hevy adapter.
 *
 * The client owns this vocabulary so adapters can only present the same
 * outcome; they cannot accidentally grow incompatible retry/error taxonomies.
 */
import { Effect, Exit } from "effect";

export type HevyOperationSafety =
	| "read"
	| "idempotent-write"
	| "non-idempotent-write";

export type HevyRequestPhase =
	| "before-dispatch"
	| "dispatch"
	| "response-headers"
	| "response-content"
	| "backoff"
	| "completed";

export type HevyCommitState = "not_sent" | "confirmed" | "unknown";

export type HevyExecutionOutcome =
	| "success"
	| "expected"
	| "retryable_failure"
	| "terminal_failure"
	| "cancelled"
	| "deadline_exceeded";

export interface HevyExecutionOutcomeDetails {
	readonly outcome: HevyExecutionOutcome;
	readonly phase: HevyRequestPhase;
	readonly operation_safety: HevyOperationSafety;
	readonly commit_state: HevyCommitState;
	readonly safe_to_retry: boolean;
	readonly status?: number;
	readonly code?: string;
}

/** Caller-owned control for one logical operation (not one retry attempt). */
export interface HevyExecutionControl {
	readonly signal?: AbortSignal;
	/** Absolute epoch milliseconds supplied by the caller; never reset. */
	readonly deadline?: number;
}

export interface HevyExecutionOptions extends HevyExecutionControl {
	/** Per-operation timeout in milliseconds; overrides the client default. */
	readonly timeoutMs?: number;
}

/** Request options shared by the curated client and generated adapters. */
export interface HevyRequestOptions extends HevyExecutionOptions {}

export function isDeadlineExceeded(deadline: number | undefined): boolean {
	return deadline !== undefined && Date.now() >= deadline;
}

export function remainingDeadlineMs(deadline: number | undefined): number {
	return deadline === undefined
		? Number.POSITIVE_INFINITY
		: deadline - Date.now();
}

export function operationSafetyForMethod(method: string): HevyOperationSafety {
	const normalizedMethod = method.toUpperCase();
	if (["GET", "HEAD", "OPTIONS"].includes(normalizedMethod)) {
		return "read";
	}
	if (["PUT", "DELETE"].includes(normalizedMethod)) {
		return "idempotent-write";
	}
	return "non-idempotent-write";
}

export function canRetryOperation(
	safety: HevyOperationSafety,
	phase: HevyRequestPhase,
): boolean {
	if (safety === "non-idempotent-write") return false;
	return (
		phase === "before-dispatch" ||
		phase === "dispatch" ||
		phase === "response-headers" ||
		phase === "response-content" ||
		phase === "backoff"
	);
}

export function commitStateFor(
	safety: HevyOperationSafety,
	phase: HevyRequestPhase,
	confirmed: boolean,
): HevyCommitState {
	if (safety === "read") return confirmed ? "confirmed" : "not_sent";
	if (confirmed) return "confirmed";
	return phase === "before-dispatch" ? "not_sent" : "unknown";
}

export interface HevyExecutionSignal {
	readonly signal: AbortSignal;
	readonly abort: (reason?: Error | string | DOMException) => void;
	readonly cleanup: () => void;
	readonly deadlineTriggered: () => boolean;
}

/**
 * Build a signal that follows both caller cancellation and one absolute
 * deadline. The returned cleanup function must be called when the operation
 * completes so a long-lived server does not retain timers/listeners.
 */
export function createExecutionSignal(
	control: HevyExecutionControl,
): HevyExecutionSignal {
	const controller = new AbortController();
	let deadlineTriggered = false;
	let cleaned = false;
	const abortFromCaller = () => {
		if (!controller.signal.aborted) controller.abort(control.signal?.reason);
	};
	if (control.signal?.aborted) abortFromCaller();
	else
		control.signal?.addEventListener("abort", abortFromCaller, { once: true });
	let timer: ReturnType<typeof setTimeout> | undefined;
	if (control.deadline !== undefined) {
		const delay = Math.max(0, control.deadline - Date.now());
		timer = setTimeout(() => {
			// Preserve a caller cancellation already observed at this
			// checkpoint. Otherwise a later deadline callback could
			// reclassify the request after cancellation won the race.
			if (controller.signal.aborted) return;
			deadlineTriggered = true;
			controller.abort(
				new DOMException("Operation deadline exceeded", "TimeoutError"),
			);
		}, delay);
	}
	return {
		signal: controller.signal,
		abort: (reason?: Error | string | DOMException) => {
			if (!controller.signal.aborted) controller.abort(reason);
		},
		cleanup: () => {
			if (cleaned) return;
			cleaned = true;
			if (timer !== undefined) clearTimeout(timer);
			control.signal?.removeEventListener("abort", abortFromCaller);
		},
		deadlineTriggered: () => deadlineTriggered,
	};
}

/**
 * Run a Promise-free execution boundary with guaranteed signal cleanup.
 *
 * The existing client remains Promise-based for compatibility. New Effect
 * integrations can use this helper to ensure deadline timers and caller
 * listeners are released on success, failure, or interruption.
 */
export function withExecutionSignal<A, E, R>(
	control: HevyExecutionControl,
	use: (execution: HevyExecutionSignal) => Effect.Effect<A, E, R>,
): Effect.Effect<A, E, R> {
	return Effect.acquireUseRelease(
		Effect.sync(() => createExecutionSignal(control)),
		use,
		(execution, exit) =>
			Effect.sync(() => {
				if (!Exit.isSuccess(exit) && Exit.hasInterrupts(exit)) {
					execution.abort(
						new DOMException("Execution interrupted", "AbortError"),
					);
				}
				execution.cleanup();
			}),
	);
}

export function isAbortLike<T>(error: T): boolean {
	if (!(error instanceof Error)) return false;
	return error.name === "AbortError" || error.name === "TimeoutError";
}

import { Effect, Predicate } from "effect";
import { z } from "zod";
import type {
	BodyMeasurement,
	CreateCustomExerciseRequestBody,
	GetV1BodyMeasurementsDate200,
	GetV1BodyMeasurements200,
	GetV1BodyMeasurementsQuery,
	GetV1ExerciseHistoryExercisetemplateid200,
	GetV1ExerciseHistoryExercisetemplateidQuery,
	GetV1ExerciseTemplatesExercisetemplateid200,
	GetV1ExerciseTemplates200,
	GetV1ExerciseTemplatesQuery,
	GetV1RoutineFolders200,
	GetV1RoutineFoldersFolderid200,
	GetV1RoutineFoldersQuery,
	GetV1Routines200,
	GetV1RoutinesQuery,
	GetV1RoutinesRoutineid200,
	UserInfoResponse,
	GetV1WorkoutsCount200,
	GetV1WorkoutsEvents200,
	GetV1WorkoutsEventsQuery,
	GetV1Workouts200,
	GetV1WorkoutsQuery,
	GetV1WorkoutsWorkoutid200,
	PostRoutinesRequestBody,
	PostRoutineFolderRequestBody,
	PostV1BodyMeasurements200,
	PostV1ExerciseTemplates200,
	PostV1Routines201,
	PostV1RoutineFolders201,
	PostV1Workouts201,
	PostWorkoutsRequestBody,
	PutBodyMeasurement,
	PutRoutinesRequestBody,
	PutV1BodyMeasurementsDateStatus200,
	PutV1RoutinesRoutineid200,
	PutV1WorkoutsWorkoutid200,
} from "./types.js";
import type { HevyRequestOptions } from "./execution.js";
import type { RequestConfig, ResponseConfig } from "./fetch.ts";
import {
	ApiError,
	NetworkError,
	NotFoundError,
	RateLimitError,
	ValidationError,
} from "./effect-errors.js";
import {
	canonicalEndpointIdentity,
	expectedGet404Outcome,
} from "./endpoint-policy.js";
import { HevyHttpError } from "./hevy-http-error.js";

/**
 * Private attachment used to connect a curated Promise client to its native
 * request interpreter without adding an Effect method to `HevyClient`.
 */
export const NATIVE_REQUEST_EFFECT = Symbol("native-request-effect");

export type NativeRequestEffect = <TData, TVariables = unknown>(
	config: RequestConfig<TVariables> & {
		readonly hevyDeadline?: number;
		readonly hevyTimeoutMs?: number;
	},
) => Effect.Effect<ResponseConfig<TData>, unknown>;

export type HevyRequestEffectError =
	| NotFoundError
	| ValidationError
	| RateLimitError
	| ApiError
	| NetworkError
	| Error;

export interface HevyRequestEffectClient {
	getWorkouts(
		params?: GetV1WorkoutsQuery,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1Workouts200, HevyRequestEffectError>;
	getWorkout(
		workoutId: string,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1WorkoutsWorkoutid200, HevyRequestEffectError>;
	createWorkout(
		data: PostWorkoutsRequestBody,
		options?: HevyRequestOptions,
	): Effect.Effect<PostV1Workouts201, HevyRequestEffectError>;
	updateWorkout(
		workoutId: string,
		data: PostWorkoutsRequestBody,
		options?: HevyRequestOptions,
	): Effect.Effect<PutV1WorkoutsWorkoutid200, HevyRequestEffectError>;
	getWorkoutEvents(
		params?: GetV1WorkoutsEventsQuery,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1WorkoutsEvents200, HevyRequestEffectError>;
	getWorkoutCount(
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1WorkoutsCount200, HevyRequestEffectError>;
	getRoutines(
		params?: GetV1RoutinesQuery,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1Routines200, HevyRequestEffectError>;
	getRoutineById(
		routineId: string,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1RoutinesRoutineid200, HevyRequestEffectError>;
	createRoutine(
		data: PostRoutinesRequestBody,
		options?: HevyRequestOptions,
	): Effect.Effect<PostV1Routines201, HevyRequestEffectError>;
	updateRoutine(
		routineId: string,
		data: PutRoutinesRequestBody,
		options?: HevyRequestOptions,
	): Effect.Effect<PutV1RoutinesRoutineid200, HevyRequestEffectError>;
	getExerciseTemplates(
		params?: GetV1ExerciseTemplatesQuery,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1ExerciseTemplates200, HevyRequestEffectError>;
	getExerciseTemplate(
		templateId: string,
		options?: HevyRequestOptions,
	): Effect.Effect<
		GetV1ExerciseTemplatesExercisetemplateid200,
		HevyRequestEffectError
	>;
	getExerciseHistory(
		exerciseTemplateId: string,
		params?: GetV1ExerciseHistoryExercisetemplateidQuery,
		options?: HevyRequestOptions,
	): Effect.Effect<
		GetV1ExerciseHistoryExercisetemplateid200,
		HevyRequestEffectError
	>;
	createExerciseTemplate(
		data: CreateCustomExerciseRequestBody,
		options?: HevyRequestOptions,
	): Effect.Effect<PostV1ExerciseTemplates200, HevyRequestEffectError>;
	getRoutineFolders(
		params?: GetV1RoutineFoldersQuery,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1RoutineFolders200, HevyRequestEffectError>;
	getRoutineFolder(
		folderId: string,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1RoutineFoldersFolderid200, HevyRequestEffectError>;
	createRoutineFolder(
		data: PostRoutineFolderRequestBody,
		options?: HevyRequestOptions,
	): Effect.Effect<PostV1RoutineFolders201, HevyRequestEffectError>;
	getBodyMeasurements(
		params?: GetV1BodyMeasurementsQuery,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1BodyMeasurements200, HevyRequestEffectError>;
	getBodyMeasurement(
		date: string,
		options?: HevyRequestOptions,
	): Effect.Effect<GetV1BodyMeasurementsDate200, HevyRequestEffectError>;
	createBodyMeasurement(
		data: BodyMeasurement,
		options?: HevyRequestOptions,
	): Effect.Effect<PostV1BodyMeasurements200, HevyRequestEffectError>;
	updateBodyMeasurement(
		date: string,
		data: PutBodyMeasurement,
		options?: HevyRequestOptions,
	): Effect.Effect<PutV1BodyMeasurementsDateStatus200, HevyRequestEffectError>;
	getUserInfo(
		options?: HevyRequestOptions,
	): Effect.Effect<UserInfoResponse, HevyRequestEffectError>;
}

type RequestExecutionControl = {
	readonly signal?: AbortSignal;
	readonly hevyDeadline?: number;
	readonly hevyTimeoutMs?: number;
};

type RequestEffectMethod = (...args: never[]) => void;

type RequestEffectAttachment = {
	readonly requestEffect: NativeRequestEffect;
};

type CuratedClientWithNativeRequestEffect = {
	readonly [NATIVE_REQUEST_EFFECT]?: NativeRequestEffect;
} & (
	| { readonly getWorkouts: RequestEffectMethod }
	| { readonly getWorkout: RequestEffectMethod }
	| { readonly getRoutines: RequestEffectMethod }
	| { readonly getRoutineById: RequestEffectMethod }
);

type RequestEffectOwner =
	| RequestEffectAttachment
	| CuratedClientWithNativeRequestEffect;

const functionSchema = z.function();

function isNativeRequestEffect(
	value: NativeRequestEffect | undefined,
): value is NativeRequestEffect {
	return functionSchema.safeParse(value).success;
}

/**
 * Return the request interpreter owned by a curated client.
 *
 * This is intentionally available only from the client's internal subpath.
 * The returned interpreter is the same one used by every Promise method on
 * the client, including its retry, timeout, abort, and error behavior.
 */
export function getNativeRequestEffect(
	client: RequestEffectOwner,
): NativeRequestEffect {
	const requestEffect =
		"requestEffect" in client
			? client.requestEffect
			: client[NATIVE_REQUEST_EFFECT];
	if (!isNativeRequestEffect(requestEffect)) {
		throw new TypeError(
			"Expected a Hevy client with the internal request Effect seam",
		);
	}
	return requestEffect;
}

const noExecutionControl = {};

function executionControl(
	options: HevyRequestOptions | undefined,
): RequestExecutionControl {
	if (options === undefined) return noExecutionControl;
	const control = {
		signal: options.signal,
		hevyDeadline: options.deadline,
		hevyTimeoutMs: options.timeoutMs,
	} satisfies RequestExecutionControl;
	return control;
}

function retryAfterSeconds(error: HevyHttpError): number | undefined {
	const value = error.headers?.get("retry-after");
	if (value === null || value === undefined || value.length === 0) {
		return undefined;
	}
	const seconds = Number(value);
	return Number.isFinite(seconds) && seconds >= 0 ? seconds : undefined;
}

function requestPage(config: RequestConfig<unknown>): number | undefined {
	const query = config.query ?? config.params;
	return Predicate.isObject(query) && Predicate.isNumber(query.page)
		? query.page
		: undefined;
}

type RequestIdentity = {
	readonly method: string;
	readonly endpoint: string;
	readonly page?: number;
};

function requestIdentity(
	config: RequestConfig<unknown>,
	cause: unknown,
): RequestIdentity {
	const method = (
		config.method ?? (cause instanceof HevyHttpError ? cause.method : "GET")
	).toUpperCase();
	const endpoint = canonicalEndpointIdentity(
		config.url ?? (cause instanceof HevyHttpError ? cause.endpoint : ""),
	);
	return {
		method,
		endpoint,
		page: requestPage(config),
	} satisfies RequestIdentity;
}

function executionMetadata(error: HevyHttpError) {
	return {
		phase: error.phase,
		operationSafety: error.operationSafety,
		commitState: error.commitState,
		safeToRetry: error.safeToRetry,
		outcome: error.outcome,
	};
}

function networkError(cause: unknown, identity: RequestIdentity): NetworkError {
	const httpError = cause instanceof HevyHttpError ? cause : undefined;
	return new NetworkError({
		code: httpError?.code ?? "ERR_NETWORK",
		endpoint: identity.endpoint,
		method: identity.method,
		phase: httpError?.phase,
		operationSafety: httpError?.operationSafety,
		commitState: httpError?.commitState,
		safeToRetry: httpError?.safeToRetry,
		outcome: httpError?.outcome,
		retryCount: httpError?.hevyRetryCount,
		retryExhausted: httpError?.hevyRetryExhausted === true,
	});
}

function mapRequestError(
	cause: unknown,
	config: RequestConfig<unknown>,
): HevyRequestEffectError {
	const identity = requestIdentity(config, cause);
	if (!(cause instanceof HevyHttpError) || cause.status === undefined) {
		return networkError(cause, identity);
	}
	const { status } = cause;
	if (status === 404) {
		return new NotFoundError({
			status,
			method: identity.method,
			endpoint: identity.endpoint,
			expected:
				expectedGet404Outcome(
					identity.endpoint,
					identity.method,
					status,
					identity.page,
				) !== undefined,
			...executionMetadata(cause),
		});
	}
	if (status === 400) {
		return new ValidationError({
			status,
			method: identity.method,
			endpoint: identity.endpoint,
			responseError: cause.responseError,
			...executionMetadata(cause),
		});
	}
	if (status === 429) {
		return new RateLimitError({
			status,
			method: identity.method,
			endpoint: identity.endpoint,
			retryAfterSeconds: retryAfterSeconds(cause),
			...executionMetadata(cause),
			retryCount: cause.hevyRetryCount,
			retryExhausted: cause.hevyRetryExhausted,
		});
	}
	return new ApiError({
		status,
		method: identity.method,
		endpoint: identity.endpoint,
		...executionMetadata(cause),
	});
}

function requestDataEffect<TData, TVariables = unknown>(
	requestEffect: NativeRequestEffect,
	config: RequestConfig<TVariables>,
	options?: HevyRequestOptions,
): Effect.Effect<TData, HevyRequestEffectError> {
	return requestEffect({
		...config,
		...executionControl(options),
	}).pipe(
		Effect.map((response) => response.data as TData),
		Effect.mapError((cause) =>
			mapRequestError(cause, config as RequestConfig<unknown>),
		),
	);
}

