	const bearer = parseBearerApiKey(authorization);
	return {
		requestId: request.headers.get("cf-ray") ?? crypto.randomUUID(),
		method: request.method,
		path: new URL(request.url).pathname,
		origin: request.headers.get("origin"),
		userAgent: request.headers.get("user-agent"),
		authMode: !authorization
			? "none"
			: !bearer
				? "invalid"
				: hasOAuthAccessTokenFormat(bearer)
					? "oauth"
					: "bearer",
		oauthEnabled: isOAuthEnabled(env),
	};
}

function validateOrigin(
	request: Request,
	env: WorkerEnv,
): string | null | Response {
	const origin = request.headers.get("origin");
	const url = new URL(request.url);
	if (!origin) return null;
	if (
		origin === "null" &&
		request.method === "POST" &&
		url.pathname === OAUTH_AUTHORIZE_PATH &&
		isOAuthEnabled(env)
	) {
		// Sandboxed browser contexts submit OAuth consent forms with an opaque
		// origin. Keep this exception route-specific; never allow it for MCP.
		return origin;
	}
	if (env.MCP_DISABLE_ORIGIN_CHECK?.trim().toLowerCase() === "true") {
		return origin;
	}
	if (origin === url.origin) return origin;
	if (!parseAllowedOrigins(env.MCP_ALLOWED_ORIGINS).has(origin)) {
		console.warn({
			event: "worker.origin_rejected",
			requestId: request.headers.get("cf-ray") ?? null,
			method: request.method,
			path: url.pathname,
			origin,
		});
		return new Response("Forbidden", {
			status: 403,
			headers: { Vary: "Origin" },
		});
	}
	return origin;
}

function corsHeaders(origin: string): Headers {
	return new Headers({
		"Access-Control-Allow-Origin": origin,
		Vary: "Origin",
	});
}

function withCors(response: Response, origin: string | null): Response {
	if (!origin) return response;
	const headers = new Headers(response.headers);
	for (const [key, value] of corsHeaders(origin)) headers.set(key, value);
	return new Response(response.body, {
		status: response.status,
		statusText: response.statusText,
		headers,
	});
}

function response(
	message: string,
	status: number,
	origin: string | null,
	headers?: Headers | Record<string, string>,
): Response {
	return withCors(new Response(message, { status, headers }), origin);
}

function resolveHevyApiBaseUrl(value: string | undefined): string {
	if (value === undefined) return HEVY_API_BASE_URL;

	let url: URL;
	try {
		url = new URL(value);
	} catch {
		throw new TypeError("Invalid Hevy API base URL");
	}
	if (
		(url.protocol !== "http:" && url.protocol !== "https:") ||
		url.username ||
		url.password ||
		url.search ||
		url.hash ||
		url.pathname.replace(/\/+$/, "")
	) {
		throw new TypeError("Invalid Hevy API base URL");
	}
	return url.origin;
}

function createDefaultValidationClient(
	apiKey: string,
	baseUrl: string,
): HevyClient {
	return createHevyClient({
		apiKey,
		baseUrl,
		maxGetRetries: 0,
		timeoutMs: WORKER_VALIDATION_TIMEOUT_MS,
	});
}

function createDefaultRequestClient(
	apiKey: string,
	baseUrl: string,
	onLog: HevyClientFactoryContext["onLog"],
): HevyClient {
	return createHevyClient({ apiKey, baseUrl, onLog });
}

function createDefaultServer(
	createClient: CreateHevyMcpServerOptions["createClient"],
	lifecycleSignal?: AbortSignal,
	executionDeadline?: number,
	observer?: CreateHevyMcpServerOptions["observer"],
): McpServer {
	return createHevyMcpServer({
		createClient,
		observer,
		lifecycleSignal,
		executionDeadline,
	});
}

function createDefaultTransport(): WebStandardStreamableHTTPServerTransport {
	return new WebStandardStreamableHTTPServerTransport({
		sessionIdGenerator: undefined,
	});
}

function logWorkerFailure(
	context: string,
	error: Error | string,
	fields: Partial<WorkerRequestLogContext> = {},
): void {
	console.error({
		event: "worker.error",
		context,
		...fields,
		...createSafeErrorDiagnostic(error),
	});
}
function logOAuthResponse(
	context: WorkerRequestLogContext,
	status: number,
): void {
	if (status < 400) return;
	console.warn({
		event: "worker.oauth_response",
		...context,
		status,
	});
}

function executionHttpResponse(
	error: Error | string,
	message: string,
	status: number,
	origin: string | null,
): Response {
	return withCors(executionResponse(error, message, status), origin);
}

function resolveWorkerDependencies(
	dependencies: WorkerDependencies,
): ResolvedWorkerDependencies {
	return {
		createValidationClient:
			dependencies.createValidationClient ?? createDefaultValidationClient,
		createRequestClient:
			dependencies.createRequestClient ?? createDefaultRequestClient,
		createServer: dependencies.createServer ?? createDefaultServer,
		createTransport: dependencies.createTransport ?? createDefaultTransport,
		createObserver:
			dependencies.createObserver ??
			((options) => createWorkerToolObserver(options)),
	};
}

async function validateHevyApiKey(
	apiKey: string,
	hevyApiBaseUrl: string,
	createValidationClient: ResolvedWorkerDependencies["createValidationClient"],
	options?: HevyRequestOptions,
): Promise<HevyApiKeyValidation> {
	try {
		const validationDeadline = Math.min(
			options?.deadline ?? Number.POSITIVE_INFINITY,
			Date.now() + WORKER_VALIDATION_TIMEOUT_MS,
		);
		await createValidationClient(apiKey, hevyApiBaseUrl).getUserInfo({
			...options,
			deadline: validationDeadline,
		});
		return "valid";
	} catch (error) {
		if (options?.signal?.aborted) throw error;
		if (isHevyHttpError(error) && error.outcome === "deadline_exceeded") {
			throw error;
		}
		if (
			isHevyHttpError(error) &&
			(error.status === 401 || error.status === 403)
		) {
			return "invalid";
		}
		throw error;
	}
}

async function serveMcpRequest(
	request: Request,
	apiKey: string,
	hevyApiBaseUrl: string,
	dependencies: ResolvedWorkerDependencies,
	deadline: number,
): Promise<Response> {
	try {
		const geography = getCloudflareGeography(request);
		const observer = dependencies.createObserver({
			userHash: await createWorkerUserHash(apiKey),
			cloudflareColo: getCloudflareColo(request),
			geoLocalityName: geography.localityName,
			geoLocalityRegion: geography.localityRegion,
			geoCountryCode: geography.countryCode,
		});
		const server = dependencies.createServer(
			({ onLog }) =>
				dependencies.createRequestClient(apiKey, hevyApiBaseUrl, onLog),
			request.signal,
			deadline,
			observer,
		);
		const transport = dependencies.createTransport();
		transport.onerror = (error) => {
			logWorkerFailure("streamable-http-transport", error);
		};
		await server.connect(transport);
		return await transport.handleRequest(request);
	} catch (error) {
		const normalizedError = error instanceof Error ? error : String(error);
		logWorkerFailure("mcp-request-processing", normalizedError);
		return executionHttpResponse(
			normalizedError,
			"Unable to process MCP request",
			500,
			null,
		);
	}
}

export function createWorkerHandler(dependencies: WorkerDependencies = {}) {
	const resolved = resolveWorkerDependencies(dependencies);

	return async function handleRequest(
		request: Request,
		env: WorkerEnv,
		ctx?: ExecutionContext,
	): Promise<Response> {
		const url = new URL(request.url);
		if (url.pathname !== MCP_PATH)
			return new Response("Not found", { status: 404 });

		const originResult = validateOrigin(request, env);
		if (originResult instanceof Response) return originResult;
		const origin = originResult;
		let hevyApiBaseUrl: string;
		try {
			hevyApiBaseUrl = resolveHevyApiBaseUrl(env.HEVY_API_BASE_URL);
		} catch {
			return response("Worker configuration error", 500, origin);
		}

		if (request.method === "OPTIONS") {
			const headers = origin ? corsHeaders(origin) : new Headers();
			headers.set("Access-Control-Allow-Methods", CORS_ALLOWED_METHODS);
			headers.set("Access-Control-Allow-Headers", CORS_ALLOWED_HEADERS);
			headers.set("Access-Control-Max-Age", "86400");
			return new Response(null, { status: 204, headers });
		}

		if (request.method !== "POST") {
			return response("Method not allowed", 405, origin, {
				Allow: CORS_ALLOWED_METHODS,
			});
		}

		const apiKey = parseBearerApiKey(request.headers.get("authorization"));
		if (!apiKey) {
			return response("Unauthorized", 401, origin, {
				"WWW-Authenticate": "Bearer",
			});
		}

		const deadline = Date.now() + WORKER_INVOCATION_TIMEOUT_MS;
		let validation: HevyApiKeyValidation;
		try {
			validation = await validateHevyApiKeyResilient(
				apiKey,
				hevyApiBaseUrl,
				resolved.createValidationClient,
				validateHevyApiKey,
				env,
				{
					signal: request.signal,
					// One absolute deadline for the whole validation phase, shared
					// across the wrapper's retries. Passing the full invocation
					// deadline instead would let each retry's inner validateHevyApiKey
					// re-anchor its own now+WORKER_VALIDATION_TIMEOUT_MS window, so
					// three attempts could consume ~3x the budget this cap reserves
					// for MCP execution.
					deadline: Math.min(
						deadline,
						Date.now() + WORKER_VALIDATION_TIMEOUT_MS,
					),
				},
				// Pass the context through as-is: when it's absent (direct callers),
				// the wrapper awaits the cache write inline rather than handing it to
				// a no-op waitUntil that would drop it.
				ctx,
			);
		} catch (error) {
			const normalizedError = error instanceof Error ? error : String(error);
			logWorkerFailure("hevy-key-validation", normalizedError);
			return executionHttpResponse(
				normalizedError,
				"Unable to validate the Hevy API key",
				502,
				origin,
			);
		}
		if (validation === "invalid") {
			return response("Unauthorized", 401, origin, {
				"WWW-Authenticate": "Bearer",
			});
		}

		return withCors(
			await serveMcpRequest(
				request,
				apiKey,
				hevyApiBaseUrl,
				resolved,
				deadline,
			),
			origin,
		);
	};
}

function createWorkerOAuthProvider(
	resolved: ResolvedWorkerDependencies,
): HevyOAuthWorker<WorkerEnv> {
	return createHevyOAuthProvider<WorkerEnv>({
		validateApiKey: async (apiKey, env, signal, deadline) => {
			let hevyApiBaseUrl: string;
			try {
				hevyApiBaseUrl = resolveHevyApiBaseUrl(env.HEVY_API_BASE_URL);
			} catch {
				return "config-error";
			}
			// No ExecutionContext reaches this dependency today (the
			// HevyOAuthDependencies.validateApiKey interface doesn't thread one),
			// so the cache write stays awaited here rather than deferred via
			// waitUntil.
			return validateHevyApiKeyResilient(
				apiKey,
				hevyApiBaseUrl,
				resolved.createValidationClient,
				validateHevyApiKey,
				env,
				{
					signal,
					// Cap the whole validation phase (see the bearer path) so the
					// wrapper's retries share one deadline instead of re-anchoring.
					deadline: Math.min(
						deadline ?? Date.now() + WORKER_INVOCATION_TIMEOUT_MS,
						Date.now() + WORKER_VALIDATION_TIMEOUT_MS,
					),
				},
			);
		},
		serveMcp: async (request, env, apiKey, deadline) => {
			let hevyApiBaseUrl: string;
			try {
				hevyApiBaseUrl = resolveHevyApiBaseUrl(env.HEVY_API_BASE_URL);
			} catch {
				return new Response("Worker configuration error", { status: 500 });
			}
			return serveMcpRequest(
				request,
				apiKey,
				hevyApiBaseUrl,
				resolved,
				deadline ?? Date.now() + WORKER_INVOCATION_TIMEOUT_MS,
			);
		},
	});
}

/**
 * Compose the legacy direct-API-key handler with the optional OAuth layer.
 *
 * Without an `OAUTH_KV` binding every request takes the legacy path, so
 * existing deployments are unaffected. With the binding, `/mcp` requests
 * whose bearer value looks like an OAuth access token (and unauthenticated
 * ones, so clients receive the RFC 9728 discovery challenge) go through the
 * OAuth provider, while raw Hevy API keys keep using the legacy path.
 */
export function createWorkerFetchHandler(
	dependencies: WorkerDependencies = {},
) {
	const resolved = resolveWorkerDependencies(dependencies);
	const legacyHandler = createWorkerHandler(dependencies);
	const oauthProvider = createWorkerOAuthProvider(resolved);

	return async function handleWorkerFetch(
		request: Request,
		env: WorkerEnv,
		ctx?: ExecutionContext,
	): Promise<Response> {
		const logContext = createRequestLogContext(request, env);
		const startedAt = Date.now();
		let responseStatus: number | null = null;
		try {
			if (!isOAuthEnabled(env)) {
				if (env.OAUTH_KV != null) {
					logWorkerFailure(
						"oauth-kv-misconfigured",
						new TypeError(
							"OAUTH_KV binding is not a KV namespace; OAuth stays disabled",
						),
						logContext,
					);
				}
				const legacyResponse = await legacyHandler(request, env, ctx);
				responseStatus = legacyResponse.status;
				return legacyResponse;
			}

			const originResult = validateOrigin(request, env);
			if (originResult instanceof Response) {
				responseStatus = originResult.status;
				return originResult;
			}
			const origin = originResult;
			const url = new URL(request.url);
			if (url.pathname === MCP_PATH) {
				if (request.method === "OPTIONS") {
					const legacyResponse = await legacyHandler(request, env, ctx);
					responseStatus = legacyResponse.status;
					return legacyResponse;
				}
				const bearer = parseBearerApiKey(request.headers.get("authorization"));
				if (bearer && !hasOAuthAccessTokenFormat(bearer)) {
					const legacyResponse = await legacyHandler(request, env, ctx);
					responseStatus = legacyResponse.status;
					return legacyResponse;
				}
				const oauthResponse = await oauthProvider.fetch(
					request,
					env,
					requireExecutionContext(ctx),
				);
				responseStatus = oauthResponse.status;
				logOAuthResponse(logContext, responseStatus);
				return withCors(oauthResponse, origin);
			}
			const oauthResponse = await oauthProvider.fetch(
				request,
				env,
				requireExecutionContext(ctx),
			);
			responseStatus = oauthResponse.status;
			logOAuthResponse(logContext, responseStatus);
			return withCors(oauthResponse, origin);
		} catch (error) {
			const normalizedError = error instanceof Error ? error : String(error);
			logWorkerFailure("request", normalizedError, logContext);
			throw error;
		} finally {
			console.log({
				event: "worker.request",
				...logContext,
				status: responseStatus,
				durationMs: Date.now() - startedAt,
			});
		}
	};
}

const handleWorkerFetch = createWorkerFetchHandler();

export default {
	fetch(
		request: Request,
		env: WorkerEnv,
		ctx?: ExecutionContext,
	): Promise<Response> {
		return handleWorkerFetch(request, env, ctx);
	},
};

/// <reference types="@cloudflare/workers-types" />

import { createSafeErrorDiagnostic } from "@hevy-mcp/core";
import {
	isHevyHttpError,
	type HevyClient,
	type HevyRequestOptions,
} from "@hevy-mcp/hevy-client";
import { isOAuthEnabled, type HevyApiKeyValidation } from "./worker-oauth.js";

/** How long a successful Hevy key validation is trusted before re-checking upstream. */
export const VALIDATION_CACHE_TTL_SECONDS = 900;

const VALIDATION_CACHE_KEY_PREFIX = "keyvalid:";
/** The only value `cacheValidation` ever writes; a KV read must match it exactly. */
const VALIDATION_CACHE_SENTINEL = "valid";
/** Bound the in-memory fallback so a flood of distinct keys cannot grow it unbounded. */
export const MEMORY_CACHE_MAX_ENTRIES = 256;

/** Structural env shape this module needs; kept independent of `WorkerEnv`. */
export interface ValidationCacheEnv {
	OAUTH_KV?: unknown;
}

interface ValidationCacheKvNamespace {
	get(key: string): Promise<string | null>;
	put(
		key: string,
		value: string,
		options?: { expirationTtl?: number },
	): Promise<void>;
}

/**
 * Fallback store for isolates without a reachable KV binding (local dev,
 * unit tests, or a misconfigured OAUTH_KV). Module-scoped so a warm isolate
 * still benefits, but unlike KV it never survives a cold start and never
 * shares state across isolates. Insertion-ordered so the oldest entry is
 * evicted first once the cap is reached.
 */
const memoryCache = new Map<string, number>();

async function sha256Hex(value: string): Promise<string> {
	const digest = await crypto.subtle.digest(
		"SHA-256",
		new TextEncoder().encode(value),
	);
	return Array.from(new Uint8Array(digest), (byte) =>
		byte.toString(16).padStart(2, "0"),
	).join("");
}

async function cacheKeyFor(apiKey: string): Promise<string> {
	return `${VALIDATION_CACHE_KEY_PREFIX}${await sha256Hex(apiKey)}`;
}

function kvNamespace(
	env: ValidationCacheEnv,
): ValidationCacheKvNamespace | undefined {
	return isOAuthEnabled(env)
		? (env.OAUTH_KV as ValidationCacheKvNamespace)
		: undefined;
}

function rememberInMemory(key: string): void {
	memoryCache.set(key, Date.now() + VALIDATION_CACHE_TTL_SECONDS * 1_000);
	while (memoryCache.size > MEMORY_CACHE_MAX_ENTRIES) {
		const oldestKey = memoryCache.keys().next().value;
		if (oldestKey === undefined) break;
		memoryCache.delete(oldestKey);
	}
}

/**
 * Whether `apiKey` has an unexpired cached "valid" verdict. A hit lets a
 * transient Hevy outage (e.g. a 429) skip the upstream validation call
 * entirely for a key that was confirmed valid recently.
 */
export async function hasCachedValidation(
	apiKey: string,
	env: ValidationCacheEnv,
): Promise<boolean> {
	const key = await cacheKeyFor(apiKey);
	const kv = kvNamespace(env);
	if (kv) {
		try {
			return (await kv.get(key)) === VALIDATION_CACHE_SENTINEL;
		} catch {
			// A cache read failure must fall through to a real validation call,
			// not fail the request.
			return false;
		}
	}
	const expiresAt = memoryCache.get(key);
	if (expiresAt === undefined) return false;
	if (expiresAt <= Date.now()) {
		memoryCache.delete(key);
		return false;
	}
	return true;
}

/** Record a successful validation so a request within the TTL can skip Hevy. */
export async function cacheValidation(
	apiKey: string,
	env: ValidationCacheEnv,
): Promise<void> {
	const key = await cacheKeyFor(apiKey);
	const kv = kvNamespace(env);
	if (kv) {
		try {
			await kv.put(key, VALIDATION_CACHE_SENTINEL, {
				expirationTtl: VALIDATION_CACHE_TTL_SECONDS,
			});
		} catch {
			// Best-effort: a cache write failure must not fail an otherwise-valid request.
		}
		return;
	}
	rememberInMemory(key);
}

/** Test-only: clear the in-memory fallback so cases don't leak into each other. */
export function resetMemoryValidationCacheForTests(): void {
	memoryCache.clear();
}

/** The shape of the plain, unmodified (upstream) `validateHevyApiKey`. */
export type HevyKeyValidator = (
	apiKey: string,
	hevyApiBaseUrl: string,
	createValidationClient: (apiKey: string, baseUrl: string) => HevyClient,
	options?: HevyRequestOptions,
) => Promise<HevyApiKeyValidation>;

const VALIDATION_RETRY_MAX_ATTEMPTS = 3;
const VALIDATION_RETRY_DELAYS_MS = [300, 600];

/**
 * Whether a failed validation attempt is worth retrying.
 *
 * HTTP 429 is deliberately excluded: fast-retrying it would spend up to
 * three Hevy calls in a few seconds against the exact rate limit that
 * caused the outage this module guards against. The shared hevy-client
 * retry classification (packages/hevy-client) treats 429 as transient and
 * has no per-call override for that; carving it out there would mean
 * touching upstream-owned client internals, so the exclusion lives here
 * instead, local to this one caller.
 */
function isRetryableValidationFailure<T>(error: T): boolean {
	if (!isHevyHttpError(error)) return false;
	const status = error.status;
	if (status === 429) return false;
	return (
		status === undefined || status === 408 || (status >= 500 && status <= 599)
	);
}

function logValidationRetry<T>(
	attempt: number,
	maxAttempts: number,
	delayMs: number,
	error: T,
): void {
	console.warn({
		event: "worker.hevy_validation_retry",
		attempt,
		maxAttempts,
		delayMs,
		...createSafeErrorDiagnostic(error),
	});
}

/** Resolves after `ms`, or immediately if `signal` is already/becomes aborted. */
function delay(ms: number, signal?: AbortSignal): Promise<void> {
	if (signal?.aborted) return Promise.resolve();
	return new Promise((resolve) => {
		const onAbort = () => {
			clearTimeout(timer);
			resolve();
		};
		const timer = setTimeout(() => {
			signal?.removeEventListener("abort", onAbort);
			resolve();
		}, ms);
		signal?.addEventListener("abort", onAbort, { once: true });
	});
}

/**
 * Execution-context-like handle for deferring the cache write past the
 * response. Structural (not the full Cloudflare `ExecutionContext`) so this
 * module doesn't need to depend on callers having one.
 */
export interface WaitUntilHandle {
	waitUntil(promise: Promise<unknown>): void;
}

/**
 * Wrap the plain `validateHevyApiKey` with this fork's resilience additions:
 * a cache check/set (skips Hevy entirely on a recent "valid" verdict), and a
 * bounded retry for transient upstream failures. Never caches "invalid" or
 * thrown verdicts — only a confirmed-valid key is cached.
 *
 * When `executionContext` is supplied, the cache write is deferred via
 * `waitUntil` so it never adds latency to the response; otherwise it's
 * awaited inline (the OAuth validation path doesn't have one reachable
 * today).
 */
export async function validateHevyApiKeyResilient(
	apiKey: string,
	hevyApiBaseUrl: string,
	createValidationClient: (apiKey: string, baseUrl: string) => HevyClient,
	validate: HevyKeyValidator,
	env: ValidationCacheEnv,
	options?: HevyRequestOptions,
	executionContext?: WaitUntilHandle,
): Promise<HevyApiKeyValidation> {
	if (await hasCachedValidation(apiKey, env)) return "valid";

	for (let attempt = 1; attempt <= VALIDATION_RETRY_MAX_ATTEMPTS; attempt++) {
		try {
			const result = await validate(
				apiKey,
				hevyApiBaseUrl,
				createValidationClient,
				options,
			);
			if (result === "valid") {
				const write = cacheValidation(apiKey, env);
				if (executionContext) executionContext.waitUntil(write);
				else await write;
			}
			return result;
		} catch (error) {
			if (options?.signal?.aborted) throw error;
			if (isHevyHttpError(error) && error.outcome === "deadline_exceeded") {
				throw error;
			}
			const delayMs = VALIDATION_RETRY_DELAYS_MS[attempt - 1];
			const deadlineAllows =
				options?.deadline === undefined ||
				(delayMs !== undefined && Date.now() + delayMs < options.deadline);
			if (
				attempt >= VALIDATION_RETRY_MAX_ATTEMPTS ||
				delayMs === undefined ||
				!deadlineAllows ||
				!isRetryableValidationFailure(error)
			) {
				throw error;
			}
			logValidationRetry(
				attempt,
				VALIDATION_RETRY_MAX_ATTEMPTS,
				delayMs,
				error,
			);
			await delay(delayMs, options?.signal);
			// `delay` resolves (rather than rejects) on abort, so re-check here:
			// without this an abort during backoff would fall through to another
			// validate() call with an already-aborted signal.
			if (options?.signal?.aborted) throw error;
		}
	}
	// Unreachable: the loop always returns or throws before exhausting its
	// bound, but TypeScript needs an explicit exit.
	throw new Error(
		"validateHevyApiKeyResilient: retry loop exited without a result",
	);
}

